/// 两套 ThemeData（跟随系统；手动切换也走这里）。
abstract final class DesignTheme {
  static ThemeData of(DesignPalette p, Brightness b) => ThemeData(
    brightness: b,
    useMaterial3: true,
    scaffoldBackgroundColor: p.phone,
    canvasColor: p.phone,
    dividerColor: p.line,
    colorScheme: ColorScheme.fromSeed(
      seedColor: p.primary,
      brightness: b,
    ).copyWith(primary: p.primary, surface: p.surface, onSurface: p.text),
    appBarTheme: AppBarTheme(
      backgroundColor: p.phone,
      foregroundColor: p.text,
      elevation: 0,
    ),
    // ★ r517（DA159）：FAB 必须用令牌色。缺这一项时 M3 走
    // `primaryContainer/onPrimaryContainer`，开着「动态取色」就成壁纸色
    // （亮色实测底 (216,226,252)、字 (45,70,115)），与设计稿的
    // 「`primary` 实心 + `onPrimary` 图标」不是一个东西。
    floatingActionButtonTheme: FloatingActionButtonThemeData(
      backgroundColor: p.primary,
      foregroundColor: p.onPrimary,
    ),
    textTheme: DesignType.textTheme(p.text, p.muted, p.dim),
  );

  static ThemeData get light => of(DesignPalette.light, Brightness.light);
  static ThemeData get dark => of(DesignPalette.dark, Brightness.dark);
}

/// 动态取色的**色相层**（`ThemeExtension`）。
///
/// 由 `AppTheme.light/dark` 在"拿到的确实是动态方案"时挂上；
/// `DesignPalette.of(context)` 会读它并把 `primary/primarySoft/accent` 换成
/// 壁纸算出来的色，**中性色与语义色不动**。
@immutable
class HudDynamicHue extends ThemeExtension<HudDynamicHue> {
  const HudDynamicHue({
    this.primary,
    this.primarySoft,
    this.accent,
    this.onPrimary,
  });

  final Color? primary;
  final Color? primarySoft;
  final Color? accent;
  final Color? onPrimary;

  @override
  HudDynamicHue copyWith({
    Color? primary,
    Color? primarySoft,
    Color? accent,
    Color? onPrimary,
  }) => HudDynamicHue(
    primary: primary ?? this.primary,
    primarySoft: primarySoft ?? this.primarySoft,
    accent: accent ?? this.accent,
    onPrimary: onPrimary ?? this.onPrimary,
  );

  @override
  HudDynamicHue lerp(ThemeExtension<HudDynamicHue>? other, double t) {
    if (other is! HudDynamicHue) return this;
    Color? mix(Color? a, Color? b) =>
        a == null || b == null ? (t < 0.5 ? a : b) : Color.lerp(a, b, t);
    return HudDynamicHue(
      primary: mix(primary, other.primary),
      primarySoft: mix(primarySoft, other.primarySoft),
      accent: mix(accent, other.accent),
      onPrimary: mix(onPrimary, other.onPrimary),
    );
  }
}
